    # thousands; anything else is a decimal mark.
    s = re.sub(r"[.,](?=\d{3}(?:[.,]|$))", "", s)
    return s.replace(",", ".")


def numbers_in(text: str) -> set[str]:
    return {_canonical_number(m.group()) for m in _NUMBER.finditer(text)}


