    value = value.strip()
    if not value:
        return True
    value_numbers = numbers_in(value)
    if value_numbers:
        return value_numbers <= numbers_in(quote)
    return fuzz.partial_ratio(normalize(value), normalize(quote)) >= TEXT_VALUE_THRESHOLD


