"""Print Sonnet's field verdicts (capital, sources, ticket, sectors) per included sample record."""
import csv
import json
from pathlib import Path

ROOT = Path(r"C:\Users\matus\Desktop\Interview_Project\Project_a")
key = {r["review_id"]: r for r in csv.DictReader(open(ROOT / "data/review/review_key.csv", encoding="utf-8"))}
print(list(next(iter(key.values())).keys()))
son = {}
for p in sorted((ROOT / "data/review/sonnet").glob("s_b*.json")):
    for r in json.loads(p.read_text(encoding="utf-8")):
        son[r["review_id"]] = r
recs = {r["review_id"]: r for r in json.loads((ROOT / "data/review/review_records.json").read_text(encoding="utf-8"))}
for rid in sorted(son):
    k = key[rid]
    if "INCLUDED" not in json.dumps(k):
        continue
    s = son[rid]
    print(f"\n== {rid} {recs[rid]['name']}  cap={recs[rid].get('total_capital_eur')} method={recs[rid].get('capital_method')}")
    for f in ("capital_ok", "sources_support", "ticket_ok"):
