    records = list(latest.values())
    primary_of = merge_duplicates(records, claims_by_cand)
    members: dict[str, list[str]] = defaultdict(list)
    for cid, p in primary_of.items():
        members[p].append(cid)

    rows = []
    for rec in records:
        cid = rec["candidate_id"]
