    </div>
    <div class="chips">${i.sectors.map(s => `<span class="chip acc">${esc(SECTOR[s] || s)}</span>`).join("")}${i.stages.map(s => `<span class="chip">${esc(STAGE[s] || s)}</span>`).join("")}</div>
